def count_swaps(a: list[int]) -> int:
    swaps = 0
    n = len(a)
    for _ in range(n):
        swapped = False
        for j in range(n - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swaps += 1
                swapped = True
        if not swapped:
            break
    return swaps

