public long countSwaps(int[] a) {
    int[] buffer = new int[a.length];
    return mergeCount(a, buffer, 0, a.length - 1);
}

private long mergeCount(int[] a, int[] buf, int lo, int hi) {
    if (lo >= hi) {
        return 0;
    }
    int mid = lo + (hi - lo) / 2;
    long count = mergeCount(a, buf, lo, mid) + mergeCount(a, buf, mid + 1, hi);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            buf[k++] = a[i++];
        } else {
            buf[k++] = a[j++];
            count += (mid - i + 1);
        }
    }
    while (i <= mid) buf[k++] = a[i++];
    while (j <= hi) buf[k++] = a[j++];
    System.arraycopy(buf, lo, a, lo, hi - lo + 1);
    return count;
}

