        if lo >= hi:
            return 0
        mid = (lo + hi) // 2
        count = merge_count(lo, mid) + merge_count(mid + 1, hi)
        merged: list[int] = []
        i, j = lo, mid + 1
        while i <= mid and j <= hi:
            if a[i] <= a[j]:
                merged.append(a[i])
                i += 1
            else:
                merged.append(a[j])
                j += 1
                count += (mid - i + 1)
        merged.extend(a[i:mid + 1])
        merged.extend(a[j:hi + 1])
        a[lo:hi + 1] = merged
        return count

    return merge_count(0, len(a) - 1)

